def number_paid(apps, schema_editor):
    """Numbers the invoices paid before numbers existed, in payment order."""
    from django.utils import timezone

    from apps.storefront.envelope import _g2j

    Invoice = apps.get_model("website", "Invoice")
    next_seq: dict[str, int] = {}
    for inv in Invoice.objects.filter(paid_at__isnull=False, number__isnull=True).order_by("paid_at", "id"):
        local = timezone.localtime(inv.paid_at)
        jy, jm, _ = _g2j(local.year, local.month, local.day)
        prefix = f"{jy % 1000:03d}{jm:02d}"
        seq = next_seq.get(prefix, 101)
        inv.number, next_seq[prefix] = f"{prefix}{seq}", seq + 1
        inv.save(update_fields=["number"])


